\olsection{Computably Enumerable Sets}

\begin{defn}
A set is \emph{computably enumerable} if it is empty or the range of a
computable function.
\end{defn}

\begin{history}
Computably enumerable sets are also called \emph{recursively
  enumerable} instead. This is the original terminology, and today
both are commonly used, as well as the abbreviations ``c.e.'' and

\olsection{المجموعات القابلة للتعداد حسابيًا}

\begin{defn}
تكون المجموعة \emph{قابلة للتعداد حسابيًا} إذا كانت خالية أو كانت مدى
دالة قابلة للحساب.
\end{defn}

\begin{history}
تسمى المجموعات القابلة للتعداد حسابيًا أيضًا \emph{قابلة للتعداد
عوديًا}. وهذه هي التسمية الأصلية، ويشيع اليوم استعمال التسميتين، وكذلك
الاختصارين ``c.e.'' و``r.e.''.

\olsection{المجموعات القابلة للتعداد حسابيًا}

\begin{defn}
المجموعة \emph{قابلة للتعداد حسابيًا} متى كانت خالية، أو كانت مدى
دالة قابلة للحساب.
\end{defn}

\begin{history}
ويقال للمجموعات القابلة للتعداد حسابيًا: \emph{قابلة للتعداد
عوديًا}، وهي التسمية الأولى تاريخيًا. وقد شاع الاسمان معًا، ومعهما
الاختصاران ``c.e.'' و``r.e.''.

\olsection{Complete Computably Enumerable Sets}

\begin{defn}
A set $A$ is a \emph{complete !!{computably enumerable} set}
(under many-one reducibility) if
\begin{enumerate}
\item $A$ is computably enumerable, and
\item for any other computably enumerable set $B$, $B \leq_m A$.
\end{enumerate}
\end{defn}

In other words, complete computably enumerable sets are the
``hardest'' computably enumerable sets possible. They allow one to
answer questions about \emph{any} computably enumerable set.

\begin{thm}
$K$, $K_0$, and $K_1$ are all complete computably enumerable sets.

\olsection{المجموعات التامة القابلة للتعداد حسابيًا}

\begin{defn}
تكون المجموعة $A$ \emph{مجموعة تامة !!{computably enumerable}}
(بالنسبة إلى قابلية الاختزال متعددًا إلى واحد) إذا
\begin{enumerate}
\item كانت $A$ قابلة للتعداد حسابيًا، و
\item كان $B\leq_m A$ لكل مجموعة أخرى $B$ قابلة للتعداد حسابيًا.
\end{enumerate}
\end{defn}

وبعبارة أخرى، المجموعات التامة القابلة للتعداد حسابيًا هي «أصعب»
المجموعات الممكنة القابلة للتعداد حسابيًا. وهي تتيح الإجابة عن أسئلة
تتعلق بـ\emph{أي} مجموعة قابلة للتعداد حسابيًا.

\begin{thm}
$K$ و$K_0$ و$K_1$ كلها مجموعات تامة قابلة للتعداد حسابيًا.

\olsection{المجموعات التامة القابلة للتعداد حسابيًا}

\begin{defn}
نسمي $A$ \emph{مجموعة تامة !!{computably enumerable}}
بالنسبة إلى الاختزال متعددًا إلى واحد، إذا اجتمع الشرطان:
\begin{enumerate}
\item كانت $A$ قابلة للتعداد حسابيًا، و
\item كان $B\leq_m A$ لكل مجموعة أخرى $B$ قابلة للتعداد حسابيًا.
\end{enumerate}
\end{defn}

فهذه المجموعات التامة هي «أصعب» ما يمكن من
المجموعات القابلة للتعداد حسابيًا؛ إذ بمعرفة أجوبتها نجيب عن الأسئلة
