\item \ollabel{defn:iso-pred}for every $n$-place !!{predicate}~$P$:
  \[
  \tuple{a_1, \dots, a_n}\in \Assign{P}{M} \quad\text{iff}\quad
  \tuple{h(a_1), \dots, h(a_n)} \in \Assign{P}{M'};
  \]
\item \ollabel{defn:iso-func}for every $n$-place !!{function} $f$:
  \[
  h(\Assign{f}{M}(a_1, \dots, a_n)) =
  \Assign{f}{M'}(h(a_1), \dots, h(a_n)).
  \]
\end{enumerate}
\end{defn}

\begin{thm}
\ollabel{thm:isom}
If $\Struct{M} \iso \Struct M'$ then $\Struct{M} \elemequiv
\Struct{M'}$.
\end{thm}

\begin{defn}
An \emph{automorphism} of a structure $\Struct{M}$ is an isomorphism
of $\Struct{M}$ onto itself.
\end{defn}

\begin{prob}
Show that for any structure $\Struct{M}$, if $X$ is a definable subset
of $\Struct{M}$, and $h$ is an automorphism of $\Struct{M}$, then $X
= \Setabs{h(x)}{x \in X}$ (i.e., $X$ is fixed under $h$).

\begin{defn}
\emph{التشاكل الذاتي} لبنية~$\Struct{M}$ هو تشاكل من
$\Struct{M}$ على نفسها.
\end{defn}

\begin{prob}
بيّن أنه لأي بنية~$\Struct{M}$، إذا كانت $X$ مجموعة جزئية قابلة
للتعريف في $\Struct{M}$، وكان $h$ تشاكلًا ذاتيًا لـ$\Struct{M}$، فإن
$X = \Setabs{h(x)}{x \in X}$ (أي إن $X$ ثابتة تحت $h$).

\begin{defn}
\emph{التشاكل الذاتي} لبنية~$\Struct{M}$ هو تشاكل من
$\Struct{M}$ على نفسها.
\end{defn}

\begin{prob}
لتكن بنية~$\Struct{M}$، ولتكن $X$ مجموعة جزئية قابلة
للتعريف في $\Struct{M}$، وليكن $h$ تشاكلًا ذاتيًا لـ$\Struct{M}$.
أثبت أن $X = \Setabs{h(x)}{x \in X}$، أي إن $X$ ثابتة تحت $h$.

\begin{prop}\ollabel{prop:equiv}
  If $\Struct{N} \models !A$ for every $!A \in \Theory{M}$, then
  $\Struct{M} \elemequiv \Struct{N}$.
\end{prop}

\begin{proof}
Since $\Sat{N}{!A}$ for all $!A \in \Theory{M}$, $\Theory{M} \subseteq
\Theory{N}$. If $\Sat{N}{!A}$, then $\Sat/{N}{\lnot !A}$, so $\lnot !A
\notin \Theory{M}$. Since $\Theory{M}$ is complete, $!A \in
\Theory{M}$. So, $\Theory{N} \subseteq \Theory{M}$, and we have
$\Struct{M} \elemequiv \Struct{N}$.
\end{proof}

\begin{rem}\ollabel{remark:R}
  Consider $\Struct{R} = \langle\Real, <\rangle$, the !!{structure}
  whose domain is the set $\Real$ of the real numbers, in the !!{language}
  comprising only a 2-place !!{predicate} interpreted as the $<$
  relation over the reals. Clearly $\Struct{R}$ is !!{nonenumerable};
  however, since $\Theory{R}$ is obviously consistent, by the
  L\"owenheim--Skolem theorem it has !!a{enumerable} model, say
  $\Struct{S}$, and by \olref{prop:equiv}, $\Struct{R}
  \equiv \Struct{S}$. Moreover, since $\Struct{R}$ and $\Struct{S}$
  are not isomorphic, this shows that the converse of
  \olref[iso]{thm:isom} fails in general.

\begin{prop}\ollabel{prop:equiv}
  إذا كان $\Struct{N} \models !A$ لكل $!A \in \Theory{M}$، فإن
  $\Struct{M} \elemequiv \Struct{N}$.
\end{prop}

\begin{proof}
من الفرض $\Sat{N}{!A}$ لكل $!A \in \Theory{M}$، ولذلك
$\Theory{M} \subseteq \Theory{N}$. ولإثبات الاحتواء الآخر،
إذا كان $\Sat{N}{!A}$، امتنع $\Sat{N}{\lnot !A}$، فلزم
$\lnot !A \notin \Theory{M}$. وبما أن $\Theory{M}$ تامة،
وجب $!A \in \Theory{M}$. فثبت
$\Theory{N} \subseteq \Theory{M}$، ومن ثم
$\Struct{M} \elemequiv \Struct{N}$.
\end{proof}

\begin{rem}\ollabel{remark:R}
  لنأخذ $\Struct{R} = \langle\Real, <\rangle$، وهي الـ!!{structure}
  التي مجالها الأعداد الحقيقية~$\Real$، ولغتها الـ!!{language}
  ذات !!{predicate} واحد ثنائي يؤول بالعلاقة~$<$ على الحقيقية.
  لا ريب أن $\Struct{R}$~!!{nonenumerable}. لكن $\Theory{R}$
  متسقة، فلها بمبرهنة لوفنهايم--سكولم نموذج !!{enumerable}،
  نسمّيه $\Struct{S}$. ويلزم من \olref{prop:equiv} أن
  $\Struct{R} \equiv \Struct{S}$. ولما كانت $\Struct{R}$
  و$\Struct{S}$ غير متشاكلتين، بطل عكس \olref[iso]{thm:isom}
  على العموم.

