\olsection{بعض المجموعات المهمة}

\begin{ex}
أكثر المجموعات التي سنبحث فيها !!{element}sها أشياء رياضية. ومن
أهمها أربع مجموعات أفردت بأسماء، وهي:
\begin{multline*}
    \Nat = \{0, 1, 2, 3, \ldots\} \\
    \shoveright{\text{مجموعة الأعداد الطبيعية}}\\
    \shoveleft{\Int = \{\ldots, -2, -1, 0, 1, 2, \ldots\}} \\
    \shoveright{\text{مجموعة الأعداد الصحيحة}}\\
    \shoveleft{\Rat = \Setabs{\nicefrac{m}{n}}{m, n \in \Int\text{ و }n \neq 0}}\\
    \shoveright{\text{مجموعة الأعداد النسبية}}\\
    \shoveleft{\Real = (-\infty, \infty)}\\
    \text{مجموعة الأعداد الحقيقية (المتصل العددي)}
\end{multline*}
وكل واحدة منها \emph{لا نهائية}؛ أي إن عدد !!{element}sها لا يتناهى.
والأعداد الطبيعية في اصطلاح هذا الكتاب تشمل الصفر، كما تبين القائمة.

وكلما انتقلنا في هذه المجموعات إلى التالية ضممنا \emph{أعدادًا أخرى}
إلى ما تقدم. فـ$\Nat \subseteq \Int \subseteq \Rat \subseteq \Real$؛
لأن الطبيعي صحيح، والصحيح نسبي، والنسبي حقيقي. ثم إن
$\Nat \subsetneq \Int \subsetneq
\Rat$؛ فـ$-1$ صحيح وليس طبيعيًا، و$\nicefrac{1}{2}$ نسبي وليس صحيحًا.
وأما $\Rat \subsetneq \Real$ فليس بالمثل في الظهور، إذ يقتضي وجود
حقيقيات ليست نسبية\oliflabeldef{sfr:arith:real:realline}{، وسيأتي الرجوع
إلى ذلك في \olref[arith][real]{realline}}{}.

وقد نحتاج أيضًا إلى مجموعة الأعداد الصحيحة الموجبة $\PosInt = \{1,
2, 3, \dots\}$، وإلى مجموعة أول عددين طبيعيين وحدهما $\Bin = \{0, 1\}$.
\end{ex}

\begin{tagblock}{compsci}
\begin{ex}[السلاسل]
ومن الأمثلة مجموعة \emph{السلاسل المنتهية} $A^{*}$ على أبجدية $A$.
والسلسلة على $A$ كل متتالية منتهية من عناصر~$A$، ويدخل في ذلك
\emph{السلسلة الفارغة $\Lambda$} ضمن السلاسل على~$A$ لكل أبجدية~$A$. فمثلًا:
\begin{multline*}
\Bin^*
=\{\Lambda,0,1,00,01,10,11,\\
000,001,010,011,100,101,110,111,0000,\ldots\}.
\end{multline*}
فإذا تألفت السلسلة $x=x_{1}\ldots x_{n}\in A^{*}$ من $n$ «حروف»
من $A$، كان \emph{طولها}~$n$، وكتبنا $\len{x}=n$.
\end{ex}
\end{tagblock}

\begin{ex}[المتتاليات اللانهائية]
وللمجموعة $A$ أيضًا مجموعة~$A^\omega$، وهي مجموعة المتتاليات اللانهائية
من !!{element}s المجموعة~$A$. ومعنى المتتالية اللانهائية
$a_1a_2a_3a_4\dots$ قائمة تمتد بلا نهاية في اتجاه واحد، وكل واحد من
الأشياء فيها !!a{element} من~$A$.
\end{ex}

\end{document}

