\olsection{\printtoken{P}{subformula}}

\begin{explain}
It is often useful to talk about the !!{formula}s that ``make up'' a
given !!{formula}.  We call these its \emph{!!{subformula}s}.  Any
!!{formula} counts as !!a{subformula} of itself; a subformula of $!A$
other than $!A$ itself is a \emph{proper !!{subformula}}.
\end{explain}

\begin{defn}[Immediate !!^{subformula}]
If $!A$ is !!a{formula}, the \emph{immediate !!{subformula}s}
of $!A$ are defined inductively as follows:
\begin{enumerate}
\item Atomic !!{formula}s have no immediate !!{subformula}s.

\tagitem{prvNot}{\indcase{!A}{\lnot !B}{The only immediate
    !!{subformula} of $\indfrm$ is~$!B$.}}{}

\item \indcase{!A}{(!B \ast !C)}{The immediate !!{subformula}s of
  $\indfrm$ are $!B$ and $!C$ ($\ast$ is any one of the two-place
  connectives).}

\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{The only immediate
    !!{subformula} of $\indfrm$ is~$!B$.}}{}

\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{The only immediate
    !!{subformula} of $\indfrm$ is~$!B$.}}{}
\end{enumerate}
\end{defn}

\begin{defn}[Proper !!^{subformula}]
If $!A$ is !!a{formula}, the \emph{proper !!{subformula}s}
of $!A$ are defined recursively as follows:
\begin{enumerate}
\item Atomic !!{formula}s have no proper !!{subformula}s.

\tagitem{prvNot}{\indcase{!A}{\lnot !B}{The proper !!{subformula}s of
    $\indfrm$ are~$!B$ together with all proper !!{subformula}s
    of~$!B$.}}{}

\item \indcase{!A}{(!B \ast !C)}{The proper !!{subformula}s of
  $\indfrm$ are $!B$, $!C$, together with all proper !!{subformula}s
  of $!B$ and those of~$!C$.}

\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{The proper
    !!{subformula}s of $\indfrm$ are~$!B$ together with all proper
    !!{subformula}s of~$!B$.}}{}

\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{The proper
    !!{subformula}s of $\indfrm$ are~$!B$ together with all proper
    !!{subformula}s of~$!B$.}}{}
\end{enumerate}
\end{defn}

\begin{defn}[!!^{subformula}]
The !!{subformula}s of $!A$ are $!A$ itself together with all its
proper !!{subformula}s.
\end{defn}

\begin{explain}
Note the subtle difference in how we have defined immediate
!!{subformula}s and proper !!{subformula}s.  In the first case, we
have directly defined the immediate !!{subformula}s of a formula~$!A$
for each possible form of~$!A$.  It is an explicit definition by
cases, and the cases mirror the inductive definition of the set of
!!{formula}s.  In the second case, we have also mirrored the way the
set of all !!{formula}s is defined, but in each case we have also
included the proper !!{subformula}s of the smaller !!{formula}s $!B$,
$!C$ in addition to these !!{formula}s themselves.  This makes the
definition \emph{recursive}.  In general, a definition of a function
on an inductively defined set (in our case, !!{formula}s) is recursive
if the cases in the definition of the function make use of
the function itself. To be well defined, we must make sure, however,
that we only ever use the values of the function for arguments that
come ``before'' the one we are defining---in our case, when defining
``proper !!{subformula}'' for $(!B \ast !C)$ we only use the proper
!!{subformula}s of the ``earlier'' !!{formula}s $!B$ and $!C$.
\end{explain}

\begin{prop}
\ollabel{prop:subfrm-trans}
Suppose $!B$ is a subformula of $!A$ and $!C$ is a subformula of $!B$.
Then $!C$ is a subformula of $!A$. In other words, the subformula
relation is transitive.
\end{prop}

\olsection{\printtoken{P}{subformula}}

\begin{explain}
كثيرًا ما يكون من المفيد أن نتحدث عن ال!!{formula}s التي «تؤلف»
!!a{formula} معطاة. ونسميها \emph{!!{subformula}s} لها. وتُعَد كل
!!{formula} !!a{subformula} من نفسها؛ أما الصيغة الجزئية من~$!A$
المغايرة لـ~$!A$ نفسها فهي \emph{!!{subformula} حقيقية}.
\end{explain}

\begin{defn}[!!^{subformula} مباشرة]
إذا كانت $!A$ !!a{formula}، فتُعرّف \emph{ال!!{subformula}s
المباشرة} لـ~$!A$ استقرائيًا كما يأتي:
\begin{enumerate}
\item ليس لل!!{formula}s الذرية !!{subformula}s مباشرة.

\tagitem{prvNot}{\indcase{!A}{\lnot !B}{ال!!{subformula} المباشرة
    الوحيدة لـ~$\indfrm$ هي~$!B$.}}{}

\item \indcase{!A}{(!B \ast !C)}{ال!!{subformula}s المباشرة
  لـ~$\indfrm$ هي $!B$ و$!C$ (حيث $\ast$ أي رابط ثنائي).}

\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{ال!!{subformula}
    المباشرة الوحيدة لـ~$\indfrm$ هي~$!B$.}}{}

\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{ال!!{subformula}
    المباشرة الوحيدة لـ~$\indfrm$ هي~$!B$.}}{}
\end{enumerate}
\end{defn}

\begin{defn}[!!^{subformula} حقيقية]
إذا كانت $!A$ !!a{formula}، فتُعرّف \emph{ال!!{subformula}s
الحقيقية} لـ~$!A$ عوديًا كما يأتي:
\begin{enumerate}
\item ليس لل!!{formula}s الذرية !!{subformula}s حقيقية.

\tagitem{prvNot}{\indcase{!A}{\lnot !B}{ال!!{subformula}s الحقيقية
    لـ~$\indfrm$ هي~$!B$ مع جميع ال!!{subformula}s الحقيقية
    لـ~$!B$.}}{}

\item \indcase{!A}{(!B \ast !C)}{ال!!{subformula}s الحقيقية
  لـ~$\indfrm$ هي $!B$ و$!C$، مع جميع ال!!{subformula}s الحقيقية
  لـ~$!B$ وتلك الخاصة بـ~$!C$.}

\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{ال!!{subformula}s
    الحقيقية لـ~$\indfrm$ هي~$!B$ مع جميع ال!!{subformula}s الحقيقية
    لـ~$!B$.}}{}

\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{ال!!{subformula}s
    الحقيقية لـ~$\indfrm$ هي~$!B$ مع جميع ال!!{subformula}s الحقيقية
    لـ~$!B$.}}{}
\end{enumerate}
\end{defn}

\begin{defn}[!!^{subformula}]
ال!!{subformula}s لـ~$!A$ هي $!A$ نفسها مع جميع ال!!{subformula}s
الحقيقية لها.
\end{defn}

\begin{explain}
لاحظ الفرق الدقيق بين طريقتنا في تعريف ال!!{subformula}s المباشرة
وطريقتنا في تعريف ال!!{subformula}s الحقيقية. ففي الحالة الأولى
عرّفنا مباشرة ال!!{subformula}s المباشرة لصيغة~$!A$ في كل صورة ممكنة
لـ~$!A$. وهذا تعريف صريح بالحالات، وحالاته تحاكي التعريف الاستقرائي
لمجموعة ال!!{formula}s. وفي الحالة الثانية حاكينا أيضًا طريقة تعريف
مجموعة جميع ال!!{formula}s، لكننا أدرجنا في كل حالة ال!!{subformula}s
الحقيقية لل!!{formula}s الأصغر $!B$ و$!C$، فضلًا عن هاتين
ال!!{formula}s نفسيهما. وهذا يجعل التعريف \emph{عوديًا}. وبوجه عام
يكون تعريف دالة على مجموعة معرّفة استقرائيًا (وهي في حالتنا
ال!!{formula}s) عوديًا إذا استخدمت حالات تعريف الدالة الدالة نفسها.
ولكن لكي يكون التعريف سليمًا، يجب أن نتأكد من أننا لا نستخدم قط إلا
قيم الدالة عند وسائط «تسبق» الوسيط الذي نعرّفه---ففي حالتنا، حين
نعرّف «!!{subformula} حقيقية» لـ~$(!B \ast !C)$، لا نستخدم إلا
ال!!{subformula}s الحقيقية لل!!{formula}s «الأسبق» $!B$ و$!C$.
\end{explain}

\begin{prop}
\ollabel{prop:subfrm-trans}
افترض أن $!B$ صيغة جزئية من~$!A$، وأن $!C$ صيغة جزئية من~$!B$.
عندئذ تكون $!C$ صيغة جزئية من~$!A$. وبعبارة أخرى، علاقة الصيغة
الجزئية متعدية.
\end{prop}

\begin{prob}
أثبت \olref[fol][syn][sbf]{prop:subfrm-trans}.
\end{prob}

\olsection{\printtoken{P}{subformula}}

\begin{explain}
نحتاج كثيرًا إلى النظر في ال!!{formula}s التي تألّفت منها
!!a{formula} معطاة؛ وتلك هي \emph{!!{subformula}s} لها. وكل
!!{formula} تُعدّ !!a{subformula} من نفسها. أما الصيغة الجزئية من~$!A$
إذا كانت غير~$!A$ نفسها، فتسمى \emph{!!{subformula} حقيقية}.
\end{explain}

\begin{defn}[!!^{subformula} مباشرة]
إذا كانت $!A$ !!a{formula}، فتُعرّف \emph{ال!!{subformula}s
المباشرة} لـ~$!A$ استقرائيًا كما يأتي:
\begin{enumerate}
\item ليس لل!!{formula}s الذرية !!{subformula}s مباشرة.

\tagitem{prvNot}{\indcase{!A}{\lnot !B}{ال!!{subformula} المباشرة
    الوحيدة لـ~$\indfrm$ هي~$!B$.}}{}

\item \indcase{!A}{(!B \ast !C)}{ال!!{subformula}s المباشرة
  لـ~$\indfrm$ هي $!B$ و$!C$ (حيث $\ast$ أي رابط ثنائي).}

\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{ال!!{subformula}
    المباشرة الوحيدة لـ~$\indfrm$ هي~$!B$.}}{}

\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{ال!!{subformula}
    المباشرة الوحيدة لـ~$\indfrm$ هي~$!B$.}}{}
\end{enumerate}
\end{defn}

\begin{defn}[!!^{subformula} حقيقية]
إذا كانت $!A$ !!a{formula}، فتُعرّف \emph{ال!!{subformula}s
الحقيقية} لـ~$!A$ عوديًا كما يأتي:
\begin{enumerate}
\item ليس لل!!{formula}s الذرية !!{subformula}s حقيقية.

\tagitem{prvNot}{\indcase{!A}{\lnot !B}{ال!!{subformula}s الحقيقية
    لـ~$\indfrm$ هي~$!B$ مع جميع ال!!{subformula}s الحقيقية
    لـ~$!B$.}}{}

\item \indcase{!A}{(!B \ast !C)}{ال!!{subformula}s الحقيقية
  لـ~$\indfrm$ هي $!B$ و$!C$، مع جميع ال!!{subformula}s الحقيقية
  لـ~$!B$ وتلك الخاصة بـ~$!C$.}

\tagitem{prvAll}{\indcase{!A}{\lforall[x][!B]}{ال!!{subformula}s
    الحقيقية لـ~$\indfrm$ هي~$!B$ مع جميع ال!!{subformula}s الحقيقية
    لـ~$!B$.}}{}

\tagitem{prvEx}{\indcase{!A}{\lexists[x][!B]}{ال!!{subformula}s
    الحقيقية لـ~$\indfrm$ هي~$!B$ مع جميع ال!!{subformula}s الحقيقية
    لـ~$!B$.}}{}
\end{enumerate}
\end{defn}

\begin{defn}[!!^{subformula}]
ال!!{subformula}s لـ~$!A$ هي $!A$ نفسها مع جميع ال!!{subformula}s
الحقيقية لها.
\end{defn}

\begin{explain}
وبين تعريف ال!!{subformula}s المباشرة وتعريف ال!!{subformula}s
الحقيقية فرق ينبغي تبيّنه. فقد عيّنّا في الأول ال!!{subformula}s
المباشرة للصيغة~$!A$ بحسب كل صورة يجوز أن تكون عليها~$!A$، فكان
تعريفًا صريحًا بالحالات، على ترتيب التعريف الاستقرائي لمجموعة
ال!!{formula}s. وسلكنا في الثاني ترتيب تعريف مجموعة
ال!!{formula}s أيضًا، غير أننا أدخلنا في كل حالة ال!!{subformula}s
الحقيقية لل!!{formula}s الأصغر $!B$ و$!C$، إلى جانب هاتين
ال!!{formula}s نفسيهما. وبذلك صار التعريف \emph{عوديًا}.
وضابط العود في تعريف دالة على مجموعة محدّدة استقرائيًا، وهي هنا
ال!!{formula}s، أن تستعمل بعض حالات التعريف الدالة نفسها.
ولا يستقيم ذلك إلا إذا اقتصر الاستعمال على قيم الدالة عند وسائط
سابقة للوسيط الجاري تعريف قيمته. فحين نحدّد «!!{subformula} حقيقية»
لـ~$(!B \ast !C)$، إنما نأخذ ال!!{subformula}s الحقيقية
لل!!{formula}s السابقة في البناء، أعني $!B$ و$!C$.
\end{explain}

\begin{prop}
\ollabel{prop:subfrm-trans}
إذا كانت $!B$ صيغة جزئية من~$!A$، وكانت $!C$ صيغة جزئية من~$!B$،
لزم أن تكون $!C$ صيغة جزئية من~$!A$؛ أي إن علاقة الصيغة
الجزئية علاقة متعدية.
\end{prop}

\begin{prob}
أثبت \olref[fol][syn][sbf]{prop:subfrm-trans}.
\end{prob}

\begin{prop}
\ollabel{prop:subformula-equivs}
The following are equivalent:
\begin{enumerate}
    \item $!B$ is a sub-!!{formula} of~$!A$.
    \item $!B$ occurs in every formation sequence of~$!A$.
    \item $!B$ occurs in a minimal formation sequence of~$!A$.
\end{enumerate}
\end{prop}

\begin{prop}
\ollabel{prop:subformula-equivs}
الشروط الآتية متكافئة:
\begin{enumerate}
    \item $!B$ !!{subformula} من~$!A$.
    \item ترد $!B$ في كل متوالية تكوين لـ~$!A$.
    \item ترد $!B$ في متوالية تكوين صغرى لـ~$!A$.
\end{enumerate}
\end{prop}

\begin{prop}
\ollabel{prop:subformula-equivs}
الشروط الآتية متكافئة:
\begin{enumerate}
    \item $!B$ !!{subformula} من~$!A$.
    \item ترد $!B$ في كل متوالية تكوين لـ~$!A$.
    \item ترد $!B$ في متوالية تكوين صغرى لـ~$!A$.
\end{enumerate}
\end{prop}

