أثبت \olref[fol][syn][sbf]{prop:subfrm-trans}.
\end{prob}

\begin{prop}
\ollabel{prop:subformula-equivs}
The following are equivalent:
\begin{enumerate}
    \item $!B$ is a sub-!!{formula} of~$!A$.
    \item $!B$ occurs in every formation sequence of~$!A$.
    \item $!B$ occurs in a minimal formation sequence of~$!A$.
\end{enumerate}
\end{prop}

\begin{prop}
\ollabel{prop:subformula-equivs}
الشروط الآتية متكافئة:
\begin{enumerate}
    \item $!B$ !!{subformula} من~$!A$.
    \item ترد $!B$ في كل متوالية تكوين لـ~$!A$.
    \item ترد $!B$ في متوالية تكوين صغرى لـ~$!A$.
\end{enumerate}
\end{prop}

\begin{prop}
\ollabel{prop:subformula-equivs}
الشروط الآتية متكافئة:
\begin{enumerate}
    \item $!B$ !!{subformula} من~$!A$.
    \item ترد $!B$ في كل متوالية تكوين لـ~$!A$.
    \item ترد $!B$ في متوالية تكوين صغرى لـ~$!A$.
\end{enumerate}
\end{prop}

