\[
\tuple{\TMendtape \frown I \frown \TMblank, 1, q_0}.
\]
\end{defn}

\begin{explain}
نستعمل~$\frown$ رمزًا لـ\emph{الوصل}. فسلسلة الدخل تتلو علامة الطرف من جهة اليمين بلا خانة فاصلة.
\end{explain}

\begin{defn}
التهيئة $\tuple{C,m,q}$ \emph{تنتج $\tuple{C',m',q'}$ في خطوة واحدة} بحسب~$M$ إذا وفقط إذا اجتمعت الشروط:
\begin{enumerate}
\item رمز الموضع $m$ من $C$ هو $\sigma$؛
\item تعليمات $M$ تعطي $\delta(q,\sigma)=
  \tuple{q',\sigma',D}$؛
\item رمز الموضع $m$ من $C'$ هو $\sigma'$؛
\item وتتحقق إحدى الحالات:
\begin{enumerate}
\item $D=L$، وعندئذ $m'=m-1$ إن كان $m>0$، وإلا $m'=0$؛ أو
\item $D=R$ و$m'=m+1$؛ أو
\item $D=N$ و$m'=m$؛
\end{enumerate}
\item إن كان $m'=\len{C}$، كان $\len{C'}=\len{C}+1$ ورمز الموضع $m'$ من $C'$ هو~$\TMblank$؛ وإلا $\len{C'}=\len{C}$؛
\item لكل $i$ يحقق $i<\len{C}$ و$i\neq m$ تبقى $C'(i)=C(i)$.
\end{enumerate}
\end{defn}

\begin{defn}\ollabel{defn:run-output}
\emph{تشغيل $M$ على الدخل~$I$} متتالية منتهية أو لا نهائية $C_i$ من تهيئات $M$؛ أولها $C_0$ التهيئة الابتدائية لـ$M$ على~$I$، وكل $C_i$ تنتج $C_{i+1}$ في خطوة واحدة متى وجدت $C_{i+1}$. وإذا انتهت المتتالية، لم تنتج تهيئتها الأخيرة تهيئة أخرى في خطوة واحدة.

وتكون $M$ \emph{متوقفة على الدخل $I$ بعد $k$ خطوات} إذا انتهى تشغيلها إلى $C_k=\tuple{C,m,q}$، وكان رمز الموضع $m$ من~$C$ هو $\sigma$، ولم تكن $\delta(q,\sigma)$ معرفة. وحينئذ \emph{خرج}~$M$ على~$I$ هو~$O$، حيث $O$ سلسلة لا تنتهي بـ~$\TMblank$ وتحقق $C=\TMendtape\concat O\concat\TMblank^j$ لبعض $j \in \Nat$. ومعنى $\TMblank^j$ سلسلة من $j$ رموز كلها $\TMblank$.
\end{defn}

\begin{explain}
فخرج~$O$ للآلة~$M$ إما منته برمز غير~$\TMblank$، وإما أن يكون $O$ خاليًا؛ وهذه الحالة الثانية إذا كان الشريط عند الزمن~$k$ كله~$\TMblank$، سوى $\TMendtape$ في أقصى اليسار.
\end{explain}

\end{document}

\olsection{التمثيل الأحادي للأعداد}

\begin{explain}
تعمل آلات تورنغ على متتاليات من الرموز المكتوبة على أشرطتها. وبحسب
الأبجدية التي تستعملها آلة تورنغ يمكن لهذه المتتاليات أن تمثل أنواعًا
مختلفة من المدخلات والمخرجات. ومما يهمنا بوجه خاص، بالطبع، آلات
تورنغ التي تحسب دوال \emph{حسابية}، أي دوال أعداد طبيعية. ومن أبسط
طرائق تمثيل الأعداد الصحيحة الموجبة ترميزها بمتتاليات من رمز واحد
$\TMstroke$. فإذا كان $n \in \Nat$، فلتكن $\TMstroke^n$ المتتالية
الخالية إذا كان $n=0$، والمتتالية المؤلفة من $n$ بالضبط من علامات
$\TMstroke$ خلاف ذلك.
\end{explain}

\begin{defn}[الحساب]
\emph{تحسب} آلة تورنغ~$M$ الدالة $f\colon\Nat^k\to\Nat$ إذا وفقط إذا
كانت~$M$، لكل $n_1,\dots,n_k\in\Nat$، تتوقف عند الدخل
\[
\TMstroke^{n_1} \TMblank \TMstroke^{n_2} \TMblank \dots \TMblank \TMstroke^{n_k}
\]
بخرج $\TMstroke^{f(n_1,\dots,n_k)}$.
\end{defn}

\begin{prob}
  عرّف متى تحسب آلة تورنغ~$M$ الدالة $f\colon\Nat^k\to\Nat^m$.
\end{prob}

\olsection{التمثيل الأحادي للأعداد}

\begin{explain}
إنما تعمل آلات تورنغ في سلاسل الرموز على أشرطتها. ويتنوع ما تمثله هذه السلاسل من دخل وخرج بتنوع الأبجدية. ويهمنا منها خاصة ما يحسب الدوال \emph{الحسابية}، أي الدوال على الأعداد الطبيعية. ومن أيسر تمثيلات الأعداد الصحيحة الموجبة سلسلة تكرر رمزًا واحدًا $\TMstroke$. فنضع، إذا كان $n \in \Nat$، أن $\TMstroke^n$ خالية عند $n=0$، وإلا فهي سلسلة من $n$ علامات بالضبط، كلها $\TMstroke$.
\end{explain}

\begin{defn}[الحساب]
تكون آلة تورنغ~$M$ \emph{حاسبة} للدالة $f\colon\Nat^k\to\Nat$ إذا وفقط إذا كانت~$M$، لكل $n_1,\dots,n_k\in\Nat$، تقف على الدخل
\[
\TMstroke^{n_1} \TMblank \TMstroke^{n_2} \TMblank \dots \TMblank \TMstroke^{n_k}
\]
ويكون خرجها $\TMstroke^{f(n_1,\dots,n_k)}$.
\end{defn}

\begin{prob}
ضع تعريفًا لكون آلة تورنغ~$M$ تحسب الدالة $f\colon\Nat^k\to\Nat^m$.
\end{prob}

\begin{ex}\ollabel{ex:adder}
\emph{الجمع:}
لننشئ آلة تحسب $f(n,m)=n+m$. فتبدأ بكتلتين من علامات $\TMstroke$، طولهما $n$ و~$m$، وتقف على كتلة واحدة فيها $n+m$ من علامات $\TMstroke$. وبين كتلتي الدخل $\TMblank$ واحدة؛ فيكفينا ملء خانة $\TMblank$ بعلامة، ثم محو آخر~$\TMstroke$.
