\begin{defn}[Satisfaction]
\ollabel{defn:satisfaction} We can inductively define the notion of
  \emph{satisfaction of !!a{formula}~$!A$ by
  !!a{valuation}~$\pAssign{v}$}, $\pSat{v}{!A}$, as follows.
  (We write $\pSat/{v}{!A}$ to mean ``not $\pSat{v}{!A}$.'')
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{$\pSat/{v}{\indfrm}$.}}{}

\tagitem{prvTrue}{%
  \indcase{!A}{\ltrue}{$\pSat{v}{\indfrm}$.}}{}

\item \indcase{!A}{\Obj p_i}{$\pSat{v}{\indfrm}$
  iff $\pAssign{v}(\Obj p_i) = \True$.}

\tagitem{prvNot}{%
  \indcase{!A}{\lnot !B}{$\pSat{v}{\indfrm}$ iff
    $\pSat/{v}{!B}$.}}{}

\tagitem{prvAnd}{%
  \indcase{!A}{(!B \land !C)}{$\pSat{v}{\indfrm}$ iff $\pSat{v}{!B}$
    and $\pSat{v}{!C}$.}}{}

\tagitem{prvOr}{%
  \indcase{!A}{(!B \lor !C)}{$\pSat{v}{\indfrm}$ iff
    $\pSat{v}{!B}$ or $\pSat{v}{!C}$ (or both).}}{}

\tagitem{prvIf}{%
  \indcase{!A}{(!B \lif !C)}{$\pSat{v}{\indfrm}$ iff $\pSat/{v}{!B}$
    or $\pSat{v}{!C}$ (or both).}}{}

\tagitem{prvIff}{%
  \indcase{!A}{(!B \liff !C)}{$\pSat{v}{\indfrm}$ iff either both
    $\pSat{v}{!B}$ and $\pSat{v}{!C}$, or neither $\pSat{v}{!B}$
    nor $\pSat{v}{!C}$.}}{}
\end{enumerate}
If $\Gamma$ is a set of !!{formula}s, $\pSat{v}{\Gamma}$ iff
$\pSat{v}{!A}$ for every~$!A \in \Gamma$.
\end{defn}

\begin{defn}[الإرضاء]
\ollabel{defn:satisfaction} يمكننا أن نعرّف استقرائيًا مفهوم
  \emph{إرضاء !!a{formula}~$!A$ بواسطة
  !!a{valuation}~$\pAssign{v}$}، أي $\pSat{v}{!A}$، كما يأتي.
  (ونكتب $\pSat/{v}{!A}$ للدلالة على «عدم تحقق $\pSat{v}{!A}$».)
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{$\pSat/{v}{\indfrm}$.}}{}

\tagitem{prvTrue}{%
  \indcase{!A}{\ltrue}{$\pSat{v}{\indfrm}$.}}{}

\item \indcase{!A}{\Obj p_i}{$\pSat{v}{\indfrm}$
  إذا وفقط إذا كان $\pAssign{v}(\Obj p_i) = \True$.}

\tagitem{prvNot}{%
  \indcase{!A}{\lnot !B}{$\pSat{v}{\indfrm}$ إذا وفقط إذا
    $\pSat/{v}{!B}$.}}{}

\tagitem{prvAnd}{%
  \indcase{!A}{(!B \land !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق كل من $\pSat{v}{!B}$
    و$\pSat{v}{!C}$.}}{}

\tagitem{prvOr}{%
  \indcase{!A}{(!B \lor !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق
    $\pSat{v}{!B}$ أو $\pSat{v}{!C}$ (أو تحققا معًا).}}{}

\tagitem{prvIf}{%
  \indcase{!A}{(!B \lif !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق $\pSat/{v}{!B}$
    أو $\pSat{v}{!C}$ (أو تحققا معًا).}}{}

\tagitem{prvIff}{%
  \indcase{!A}{(!B \liff !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق كل من
    $\pSat{v}{!B}$ و$\pSat{v}{!C}$، أو لم يتحقق $\pSat{v}{!B}$
    ولا $\pSat{v}{!C}$.}}{}
\end{enumerate}
إذا كانت $\Gamma$ مجموعة من !!{formula}s، فإن $\pSat{v}{\Gamma}$ يتحقق إذا وفقط إذا
تحقق $\pSat{v}{!A}$ لكل~$!A \in \Gamma$.
\end{defn}

\begin{defn}[الإرضاء]
\ollabel{defn:satisfaction} هذا تعريف استقرائي لمعنى
  \emph{إرضاء !!a{formula}~$!A$ بواسطة
  !!a{valuation}~$\pAssign{v}$}، أي $\pSat{v}{!A}$، على الوجه الآتي.
  (ونكتب $\pSat/{v}{!A}$ للدلالة على «عدم تحقق $\pSat{v}{!A}$».)
\begin{enumerate}
\tagitem{prvFalse}{%
  \indcase{!A}{\lfalse}{$\pSat/{v}{\indfrm}$.}}{}

\tagitem{prvTrue}{%
  \indcase{!A}{\ltrue}{$\pSat{v}{\indfrm}$.}}{}

\item \indcase{!A}{\Obj p_i}{$\pSat{v}{\indfrm}$
  إذا وفقط إذا كان $\pAssign{v}(\Obj p_i) = \True$.}

\tagitem{prvNot}{%
  \indcase{!A}{\lnot !B}{$\pSat{v}{\indfrm}$ إذا وفقط إذا
    $\pSat/{v}{!B}$.}}{}

\tagitem{prvAnd}{%
  \indcase{!A}{(!B \land !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق كل من $\pSat{v}{!B}$
    و$\pSat{v}{!C}$.}}{}

\tagitem{prvOr}{%
  \indcase{!A}{(!B \lor !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق
    $\pSat{v}{!B}$ أو $\pSat{v}{!C}$ (أو تحققا معًا).}}{}

\tagitem{prvIf}{%
  \indcase{!A}{(!B \lif !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق $\pSat/{v}{!B}$
    أو $\pSat{v}{!C}$ (أو تحققا معًا).}}{}

\tagitem{prvIff}{%
  \indcase{!A}{(!B \liff !C)}{$\pSat{v}{\indfrm}$ إذا وفقط إذا تحقق كل من
    $\pSat{v}{!B}$ و$\pSat{v}{!C}$، أو لم يتحقق $\pSat{v}{!B}$
    ولا $\pSat{v}{!C}$.}}{}
\end{enumerate}
إذا كانت $\Gamma$ مجموعة من !!{formula}s، فإن $\pSat{v}{\Gamma}$ يتحقق إذا وفقط إذا
تحقق $\pSat{v}{!A}$ لكل~$!A \in \Gamma$.
\end{defn}

